#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.theGiantsFlesh)]
    public class TheGiantsFleshBuff : CurseBuffDefinition
    {
        public TheGiantsFleshBuff(string nsp, string name) : base(nsp, name)
        {
            AddTriggerFiltered(LevelCallbacks.POST_ENTITY_INIT, PostEnemyInitCallback, EntityTypes.ENEMY);
        }
        private void PostEnemyInitCallback(EntityCallbackParams args, CallbackResultVoid result)
        {
            var entity = args.entity;
            if (!entity.Level.HasBuff(this))
                return;
            if (!entity.IsHostileEntity())
                return;
            entity.AddBuff<TheGiantsFleshForEnemyBuff>();
        }
    }
}
